import openpyxl
from datetime import datetime
for tag,f in [('GOLDEN','/mnt/hhq/data/MiMotable/固定资产折旧台账表1.xlsx'),('TEMPLATE','/tmp/llm_rollout__w_jh0vc/mimotable_batch1_0259_template_2381_input.xlsx')]:
    wb=openpyxl.load_workbook(f, data_only=False)
    ws=wb['折旧台账表']
    print('====',tag)
    # count non-empty
    from collections import Counter
    cnt=Counter()
    for row in ws.iter_rows():
        for c in row:
            if c.value is not None:
                cnt[c.coordinate[0]]+=1
    print('nonempty by col', dict(cnt))
    # print K,L,M values rows 2-20
    for r in range(2, 20):
        vals=[]
        for c in ['K','L','M']:
            cell=ws[f'{c}{r}']
            v=cell.value
            if isinstance(v, datetime): v=v.strftime('%Y-%m-%d')
            if v is not None:
                vals.append(f'{cell.coordinate}={v!r}')
        if vals: print(r, vals)
